<?php
if(!defined('ABSPATH'))exit;
class Ostadi_Elementor_Reference_Showcase extends \Elementor\Widget_Base{
 public function get_name(){return 'ostadi-reference-showcase';} public function get_title(){return 'ویترین مقالات استادی';} public function get_icon(){return 'eicon-posts-grid';} public function get_categories(){return ['ostadi-1'];}
 protected function register_controls(){ $this->start_controls_section('content',['label'=>'محتوا']); $this->add_control('title',['label'=>'عنوان','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'جدیدترین مقالات آموزشی']); $this->add_control('subtitle',['label'=>'زیرعنوان','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'دانش، مهارت و تجربه را از بهترین منابع بیاموزید']); $this->add_control('count',['label'=>'تعداد کارت','type'=>\Elementor\Controls_Manager::NUMBER,'min'=>3,'max'=>12,'default'=>4]); $this->add_control('sidebar',['label'=>'محبوب‌ترین‌ها','type'=>\Elementor\Controls_Manager::SWITCHER,'return_value'=>'yes','default'=>'yes']); $this->end_controls_section(); }
 protected function render(){ $s=$this->get_settings_for_display(); $q=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>max(3,min(12,(int)$s['count'])),'no_found_rows'=>true]); $hero=$q->posts[0]??null; $pop=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'orderby'=>'comment_count','no_found_rows'=>true]); ?>
 <div class="ostadi-reference" dir="rtl"><header class="ostadi-ref-heading"><span class="ostadi-ref-heading__icon">▥</span><h2><?php echo esc_html($s['title']);?></h2><p><?php echo esc_html($s['subtitle']);?></p></header><div class="ostadi-ref-top"><article class="ostadi-ref-hero"><div class="ostadi-ref-hero__media"><?php if($hero&&has_post_thumbnail($hero->ID)):?><img src="<?php echo esc_url(get_the_post_thumbnail_url($hero->ID,'large'));?>" alt="<?php echo esc_attr(get_the_title($hero->ID));?>"><?php endif;?><span class="ostadi-badge">آموزش وردپرس</span></div><div class="ostadi-ref-hero__body"><span class="ostadi-badge">آموزش طراحی سایت</span><h1><?php echo $hero?esc_html(get_the_title($hero->ID)):'چگونه یک سایت حرفه‌ای بسازیم؟';?></h1><p><?php echo $hero?esc_html(wp_trim_words(get_the_excerpt($hero->ID),24)):'راهنمای کاربردی برای ساخت یک وب‌سایت آموزشی حرفه‌ای.';?></p><div class="ostadi-meta"><span>۸ دقیقه مطالعه</span><span><?php echo $hero?esc_html(get_the_date('', $hero->ID)):'امروز';?></span></div><a class="ostadi-button" href="<?php echo $hero?esc_url(get_permalink($hero->ID)):'#';?>">ادامه مطلب ←</a></div></article><?php if($s['sidebar']==='yes'):?><aside class="ostadi-ref-sidebar"><div class="ostadi-section-head"><h3>محبوب‌ترین مطالب</h3><span>♨</span></div><?php while($pop->have_posts()):$pop->the_post();?><a class="ostadi-ref-popular" href="<?php the_permalink();?>"><?php if(has_post_thumbnail()):?><img src="<?php echo esc_url(get_the_post_thumbnail_url(get_the_ID(),'medium'));?>" alt=""><?php endif;?><span><strong><?php the_title();?></strong><small><?php echo esc_html(get_the_date());?></small></span></a><?php endwhile;wp_reset_postdata();?></aside><?php endif;?></div><div class="ostadi-ref-filters"><span>نمایش:</span><a class="is-active" href="#">همه</a><a href="#">طراحی سایت</a><a href="#">برنامه‌نویسی</a><a href="#">هوش مصنوعی</a><a href="#">آموزش</a><span class="ostadi-ref-view">▦　☷</span></div><section><div class="ostadi-section-head"><h2>آخرین مقالات</h2><a href="<?php echo esc_url(get_permalink(get_option('page_for_posts')));?>">مشاهده همه ←</a></div><div class="ostadi-grid"><?php while($q->have_posts()):$q->the_post();?><article class="ostadi-card"><a class="ostadi-card__media" href="<?php the_permalink();?>"><?php if(has_post_thumbnail()):?><img src="<?php echo esc_url(get_the_post_thumbnail_url(get_the_ID(),'large'));?>" alt=""><?php endif;?><span class="ostadi-badge"><?php $c=get_the_category();echo esc_html($c?$c[0]->name:'آموزش');?></span></a><div class="ostadi-card__body"><h3><a href="<?php the_permalink();?>"><?php the_title();?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),17));?></p><div class="ostadi-meta"><span><?php echo esc_html(get_the_date());?></span><span>مطالعه مقاله</span></div></div></article><?php endwhile;wp_reset_postdata();?></div></section></div><?php }
}
